let response = $input.first().json ?? {};

if (response.data && typeof response.data === 'string') {
  try {
    response = JSON.parse(response.data);
  } catch (e) {
    throw new Error('Juvare returned text/HTML instead of JSON. Raw: ' + response.data.substring(0, 150));
  }
}

let statuses = [];
if (Array.isArray(response.statuses)) statuses = response.statuses;
else if (Array.isArray(response)) statuses = response;
else if (response.data && Array.isArray(response.data.statuses)) statuses = response.data.statuses;

if (!statuses.length) throw new Error('NJ Divert returned no records.');

const STATE_KEY = 'njDivertStateV5';
const NJ_DIVERT_URL = 'https://njdivert.juvare.com/';
const nowEastern = () => new Intl.DateTimeFormat('en-GB', { timeZone: 'America/New_York', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date());

const currentRows = {};
for (const item of statuses) {
  const id = String(item.id || item.resourceName);
  currentRows[id] = {
    id,
    resourceName: String(item.resourceName ?? '').trim(),
    county: String(item.county ?? 'Unknown').trim(),
    edStatus: String(item.edStatus ?? 'Normal').trim(),
    edStatusReason: String(item.edStatusReason ?? '').trim(),
    colorCode: String(item.colorCode ?? 'green').trim().toLowerCase(),
    comments: String(item.comments ?? '').trim(),
  };
}

const staticData = $getWorkflowStaticData('global');
const previous = staticData[STATE_KEY] ?? null;
const previousRows = previous?.rows ?? {};

const activeDiverts = [];
const clearedDiverts = [];

for (const [id, row] of Object.entries(currentRows)) {
  const oldRow = previousRows[id] ?? null;
  const isCurrentlyDivert = row.edStatus.toLowerCase() !== 'normal';
  const wasDivert = oldRow && oldRow.edStatus.toLowerCase() !== 'normal';

  if (isCurrentlyDivert) {
    activeDiverts.push({
      ...row,
      isNew: !wasDivert,
      statusChanged: oldRow && oldRow.edStatus !== row.edStatus,
      previousStatus: oldRow ? oldRow.edStatus : 'Unknown'
    });
  } else if (wasDivert && !isCurrentlyDivert) {
    clearedDiverts.push({
      ...row,
      previousStatus: oldRow.edStatus
    });
  }
}

staticData[STATE_KEY] = { rows: currentRows, lastUpdated: response.updateDateTime ?? new Date().toISOString() };

if (activeDiverts.length === 0 && clearedDiverts.length === 0) {
  return [{ json: { shouldSend: false, reason: 'All normal, no changes.', ntfyPayload: null } }];
}

const groupAndSort = (facilities) => {
  facilities.sort((a, b) => {
    if (a.county < b.county) return -1;
    if (a.county > b.county) return 1;
    if (a.resourceName < b.resourceName) return -1;
    if (a.resourceName > b.resourceName) return 1;
    return 0;
  });
  const grouped = {};
  for (const f of facilities) {
    if (!grouped[f.county]) grouped[f.county] = [];
    grouped[f.county].push(f);
  }
  return grouped;
};

const getIcon = (status, colorCode) => {
  const s = status.toLowerCase();
  if (s === 'normal') return '🟩';
  if (s === 'closed') return '⬛';
  if (colorCode === 'red' || ['psychiatric', 'specialty', 'divert', 'reroute'].includes(s)) return '🟥';
  return '🟨';
};

const groupedActive = groupAndSort(activeDiverts);
const lines = [];

if (clearedDiverts.length > 0) {
  lines.push('**RECENTLY CLEARED**');
  clearedDiverts.sort((a, b) => a.resourceName.localeCompare(b.resourceName));
  for (const f of clearedDiverts) {
    lines.push(`🟩 ${f.resourceName} (${f.county} Co.)`);
  }
  lines.push('');
}

if (activeDiverts.length > 0) {
  lines.push('**ACTIVE DIVERTS**');
  for (const [county, facilities] of Object.entries(groupedActive)) {
    lines.push(`\n*${county.toUpperCase()} COUNTY*`);
    for (const f of facilities) {
      const icon = getIcon(f.edStatus, f.colorCode);
      let statusBadge = `[${f.edStatus.toUpperCase()}]`;
      let nameLine = `**${f.resourceName}**`;

      if (f.isNew) {
        lines.push(`${icon} [NEW] ${nameLine} ${statusBadge}`);
      } else {
        lines.push(`${icon} ${nameLine} ${statusBadge}`);
      }

      let statusLine = `> Status: ${f.edStatus.toUpperCase()}`;
      if (f.statusChanged && f.previousStatus.toLowerCase() !== 'normal') {
         statusLine = `> Status: ${f.previousStatus.toUpperCase()} -> ${f.edStatus.toUpperCase()}`;
      }
      lines.push(statusLine);

      if (f.edStatusReason) lines.push(`> Reason: ${f.edStatusReason}`);
      if (f.comments) lines.push(`> Note: ${f.comments}`);
      lines.push('');
    }
  }
}

lines.push(`\nUpdated ${nowEastern()}`);

let title = 'NJ Divert Update';
if (activeDiverts.length > 0 && clearedDiverts.length > 0) {
  title = `NJ Divert: ${activeDiverts.length} Active, ${clearedDiverts.length} Cleared`;
} else if (activeDiverts.length > 0) {
  title = `NJ Divert: ${activeDiverts.length} Active Diverts`;
} else if (clearedDiverts.length > 0) {
  title = `NJ Divert: All Clear (${clearedDiverts.length} Restored)`;
}

let priority = 4;
let tags = ['hospital'];
if (activeDiverts.length === 0) {
  priority = 3;
} else {
  if (activeDiverts.some(f => f.edStatus.toLowerCase() === 'closed')) {
    priority = 5;
  }
}

const ntfyPayload = {
  topic: 'NJDivert',
  title,
  message: lines.join('\n').trim(),
  priority,
  tags,
  markdown: true,
  click: NJ_DIVERT_URL,
  actions: [
    { action: 'view', label: 'NJ Divert Portal', url: NJ_DIVERT_URL, clear: false }
  ]
};

return [{ json: { shouldSend: true, activeCount: activeDiverts.length, clearedCount: clearedDiverts.length, ntfyPayload } }];

return $input.all().map((item) => {
  const j = item.json || {};
  const p = j.ntfyPayload || {};

  const title = String(p.title || 'NJ Divert Update').trim();
  const message = String(p.message || '').trim();
  const activeCount = Number(j.activeCount || 0);
  const clearedCount = Number(j.clearedCount || 0);

  const rawKey = `${title}|${message}`;

  // Small deterministic hash so a retry of the same update keeps the same alert_id.
  let hash = 2166136261;
  for (let i = 0; i < rawKey.length; i++) {
    hash ^= rawKey.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }

  const sourceEventId = (hash >>> 0).toString(16).padStart(8, '0');
  const now = new Date().toISOString();

  let status = 'ACTIVE';
  let eventAction = 'UPDATE';

  if (activeCount === 0) {
    status = 'RESOLVED';
    eventAction = 'RESOLVED';
  } else if (clearedCount === 0) {
    eventAction = 'NEW';
  }

  const priority = Number(p.priority || 4);

  const alert = {
    schema_version: '1.0',
    alert_id: `NJ_DIVERT:${sourceEventId}`,
    source: 'NJ_DIVERT',
    source_event_id: sourceEventId,

    category: 'EMS',
    subtype: 'HOSPITAL_DIVERT',

    status,
    event_action: eventAction,

    title,
    message: message || 'NJ Divert status changed.',

    priority,

    county: '',
    municipality: '',

    location: {
      label: '',
      address: '',
      state: 'NJ',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },

    tags: ['nj-divert', 'hospital', 'ems'],

    click_url: String(p.click || ''),
    source_url: String(p.click || ''),

    observed_at: now,
    source_updated_at: null,
    received_at: now,
    expires_at: null,

    metadata: {
      active_count: activeCount,
      cleared_count: clearedCount,
      ntfy_topic: String(p.topic || 'NJDivert'),
      original_title: title
    }
  };

  alert.search_text = [
    alert.source,
    'NJ DIVERT',
    alert.category,
    alert.subtype,
    alert.status,
    alert.title,
    alert.message,
    ...alert.tags
  ].filter(Boolean).join(' ');

  return { json: alert };
});
